package com.theone.cinema;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class LanguageSelectionTest {
 @Test public void selectionDoesNotMutatePublishedLists(){CatalogEntry en=new CatalogEntry(1,"EN - Film","mp4","","","movies",0);CatalogEntry nl=new CatalogEntry(2,"NL - Film","mp4","","","movies",0);List<CatalogEntry> versions=Collections.unmodifiableList(Arrays.asList(en,nl));Map<String,List<CatalogEntry>> source=Collections.singletonMap("movies",Collections.singletonList(en));Map<String,List<CatalogEntry>> variants=Collections.singletonMap(en.key(),versions);Map<String,List<CatalogEntry>> chosen=LanguageSelection.choose(source,variants,"nl");assertSame(nl,chosen.get("movies").get(0));assertSame(en,source.get("movies").get(0));assertSame(en,versions.get(0));}
 @Test public void largeCatalogRetainsEveryTitleAndBackup(){List<CatalogEntry> entries=new ArrayList<>();Map<String,List<CatalogEntry>> variants=new HashMap<>();for(int i=1;i<=10000;i++){CatalogEntry en=new CatalogEntry(i,"EN - Title "+i,"mp4","","","movies",0,String.valueOf(i));CatalogEntry nl=new CatalogEntry(i+10000,"NL - Title "+i,"mp4","","","movies",0,String.valueOf(i));entries.add(en);variants.put(en.key(),Arrays.asList(en,nl));}Map<String,List<CatalogEntry>> chosen=LanguageSelection.choose(Collections.singletonMap("movies",entries),variants,"nl");assertEquals(10000,chosen.get("movies").size());assertEquals("nl",chosen.get("movies").get(9999).languageCode());assertEquals(Arrays.asList("en","nl"),LanguageSelection.languages(variants.values()));}
}
